import {percentageYield,atomEconomy,yieldTasks,economyTasks} from './efficiency-models.js?v=20261023-physicscomplete01';
import {showEfficiency} from './efficiency-scenes.js?v=20261023-physicscomplete01';
const input=(id,label,v='')=>`<label class="field-label" for="${id}">${label}</label><input class="lab-input" id="${id}" type="number" step="any" value="${v}">`;
export function mountEfficiencyWidget(l,p,root,{save,done,feedback}){
 const w=p.widget;w.task??=0;w.answers??={};w.passed??=[];const i=w.task,a=w.answers[i]??={},yieldMode=l.widget==='efficiency-yield',t=(yieldMode?yieldTasks:economyTasks)[i],$=s=>root.querySelector(s),kind=yieldMode?'yield':'economy',value=yieldMode?percentageYield(t.actual,t.theoretical):atomEconomy(t.numerator,t.denominator);
 root.innerHTML=`<p><b>Case ${i+1} / 3</b></p>`+(yieldMode?`<p>Theoretical maximum ${t.theoretical} g; collected product ${t.actual} g. ${t.story}</p>`+input('effPercent','Percentage yield / %',a.percent)+`<label class="field-label" for="effCause">Reason for the lower collected yield</label><select class="lab-select" id="effCause"><option value="">Choose…</option><option value="loss">Product lost during separation</option><option value="incomplete">Incomplete reversible reaction</option><option value="alternative">Alternative reaction products</option><option value="destroyed">Atoms were destroyed</option></select>`:`<p>${t.equation}. Desired product: ${t.desired}.</p><p>Relative masses: ${t.names.map((n,j)=>n+' = '+t.mrs[j]).join('; ')}. Include coefficients.</p>`+input('effNumerator','Desired product: coefficient × relative mass',a.numerator)+input('effDenominator','All reactants: sum of coefficient × relative mass',a.denominator)+input('effPercent','Atom economy / % (1 decimal place is enough)',a.percent))+`<button class="secondary" id="checkEfficiency">Check the percentage</button><button class="secondary" id="nextEfficiency">Next case →</button><p id="effProgress">${w.passed.length} / 3 cases correct</p>`;
 const fields=yieldMode?[['percent','effPercent']]:[['numerator','effNumerator'],['denominator','effDenominator'],['percent','effPercent']];fields.forEach(([k,id])=>$('#'+id).oninput=e=>{a[k]=e.target.value;save();});if(yieldMode){$('#effCause').value=a.cause||'';$('#effCause').onchange=e=>{a.cause=e.target.value;save();};}
 showEfficiency(kind,t,w.passed.includes(i)?value:null);
 $('#checkEfficiency').onclick=()=>{const near=(k,n,tol)=>a[k]!==undefined&&a[k]!==''&&Number.isFinite(Number(a[k]))&&Math.abs(Number(a[k])-n)<=tol;const ok=near('percent',value,.05)&&(yieldMode?a.cause===t.cause:near('numerator',t.numerator,.001)&&near('denominator',t.denominator,.001));
 if(!ok){feedback(yieldMode?'Divide collected mass by theoretical mass, then multiply by100. Match the stated reason; low yield never means atoms disappeared.':'Use the desired product with its coefficient in the numerator. Add ALL coefficient-weighted reactant masses in the denominator; then ×100. Do not use actual collected mass.',true);return;}
 if(!w.passed.includes(i))w.passed.push(i);save();showEfficiency(kind,t,value);$('#effProgress').textContent=w.passed.length+' / 3 cases correct';feedback(yieldMode?'Correct. The remaining mass difference is not destroyed atoms; the stated process explains the lower recovery.':'Correct. The bar compares desired-product mass contribution with all starting reactant mass from the equation.');if(w.passed.length===3){p.widgetDone=true;save();done();}
 };
 $('#nextEfficiency').onclick=()=>{w.task=(i+1)%3;save();mountEfficiencyWidget(l,p,root,{save,done,feedback});};
}
